            ['nama_lengkap' => 'RIFNALDY GUSTIAN', 'nim' => '332024169', 'email' => null, 'angkatan' => 2024, 'no_telepon' => null, 'kode_prodi' => 'DKV'],
            ['nama_lengkap' => 'FAREL MUHAMMAD IRSYAD', 'nim' => '332024172', 'email' => null, 'angkatan' => 2024, 'no_telepon' => null, 'kode_prodi' => 'DKV'],
            ['nama_lengkap' => 'AMANDA ZAVIRA', 'nim' => '332024173', 'email' => null, 'angkatan' => 2024, 'no_telepon' => null, 'kode_prodi' => 'DKV'],
            ['nama_lengkap' => 'Isabella Vanesya Br. Hutasoit', 'nim' => '332025600', 'email' => null, 'angkatan' => 2025, 'no_telepon' => '0882272473060', 'kode_prodi' => 'DKV'],
        ];

        $this->call(ProdiSeeder::class);

        $requiredProdiCodes = collect($mahasiswas)->pluck('kode_prodi')->unique();
        $availableProdiCodes = DB::table('prodi')
            ->whereIn('kode_prodi', $requiredProdiCodes)
            ->pluck('kode_prodi');
        $missingProdiCodes = $requiredProdiCodes->diff($availableProdiCodes);

        if ($missingProdiCodes->isNotEmpty()) {
            throw new RuntimeException(
                'Kode prodi belum tersedia. Jalankan KegiatanSeeder terlebih dahulu: '.$missingProdiCodes->implode(', ')
            );
        }

        $unusablePassword = Hash::make(Str::random(64));

        DB::transaction(function () use ($mahasiswas, $unusablePassword): void {
            foreach ($mahasiswas as $mahasiswa) {
                $peserta = Peserta::query()
                    ->with('user')
                    ->where('nim', $mahasiswa['nim'])
                    ->first();
                $user = $peserta?->user ?? User::query()->where('nim', $mahasiswa['nim'])->first();

                if ($user && ! $user->isMahasiswa()) {
                    throw new RuntimeException("NIM {$mahasiswa['nim']} sudah digunakan akun non-mahasiswa.");
                }

                $user ??= new User;
                $isNewUser = ! $user->exists;
                $user->name = $mahasiswa['nama_lengkap'];
                $user->nim = $mahasiswa['nim'];
                $user->role = 'mahasiswa';

                if ($isNewUser) {
                    $user->password = $unusablePassword;
                }

                if (blank($user->email) && filled($mahasiswa['email'])) {
                    $emailAlreadyUsed = User::query()
                        ->where('email', $mahasiswa['email'])
                        ->when($user->exists, fn ($query) => $query->where('id', '!=', $user->id))
                        ->exists();

                    if (! $emailAlreadyUsed) {
                        $user->email = $mahasiswa['email'];
                    }
                }

                $user->save();

                Peserta::query()->updateOrCreate(
                    ['user_id' => $user->id],
                    [
                        'nama_lengkap' => $mahasiswa['nama_lengkap'],
                        'nim' => $mahasiswa['nim'],
                        'kode_prodi' => $mahasiswa['kode_prodi'],
                        'angkatan' => $mahasiswa['angkatan'],
                        'no_telepon' => $mahasiswa['no_telepon'],
                    ]
                );
            }
        });
    }
